/**
 * Find every condition whose alias appears in the normalized message,
 * matched on word boundaries so "add" doesn't match inside "address", etc.
 * Longer aliases are checked first so more specific phrases win over
 * shorter substrings (e.g. "polycystic ovary syndrome" over a hypothetical
 * shorter overlapping alias).
 *
 * Returns an array (usually 0 or 1 items; more than 1 means the message was
 * genuinely ambiguous and the caller should ask the user to clarify rather
 * than silently guessing).
 */
export function findConditions(normalizedText) {
  const allAliases = CONDITIONS.flatMap((c) =>
    c.aliases.map((alias) => ({ alias, condition: c }))
  ).sort((a, b) => b.alias.length - a.alias.length);

  const matched = new Set();
  const results = [];

  for (const { alias, condition } of allAliases) {
    if (matched.has(condition.slug)) continue;
    const pattern = new RegExp(`\\b${escapeRegex(alias)}\\b`, 'i');
    if (pattern.test(normalizedText)) {
      matched.add(condition.slug);
      results.push(condition);
    }
  }

  return results;
}

export function getConditionBySlug(slug) {
  return CONDITIONS.find((c) => c.slug === slug) || null;
}

function escapeRegex(str) {
  return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}
